/**
 * @file chat.hpp
 * @brief Declare chat completion requests, responses, chunks, and stream events.
 */
#pragma once

#include <cstdint>
#include <functional>
#include <optional>
#include <string>
#include <vector>

#include <json/value.h>

#include "drogon_openai/error.hpp"
#include "drogon_openai/request_options.hpp"

namespace drogon_openai {

    /**
     * @brief Function invocation generated by a model.
     */
    struct ChatCompletionFunction {
        std::string name;                              ///< Function name.
        std::string arguments;                         ///< JSON-encoded arguments, kept verbatim.
        std::optional<Json::Value> parsed_arguments{}; ///< Decoded arguments from `Parse`.
    };

    /**
     * @brief Custom tool invocation generated by a model.
     */
    struct ChatCompletionCustom {
        std::string name;  ///< Custom tool name.
        std::string input; ///< Free-form input.
    };

    /**
     * @brief Function or custom tool call (`ChatCompletionMessageToolCall`).
     */
    struct ChatCompletionMessageToolCall {
        std::string id;                    ///< Tool call ID, echoed by tool messages.
        std::string type;                  ///< `function` or `custom`.
        ChatCompletionFunction function{}; ///< Function call when type is `function`.
        ChatCompletionCustom custom{};     ///< Custom call when type is `custom`.
        Json::Value raw{};                 ///< Complete tool call, including vendor fields.
    };

    /**
     * @brief One conversation message (`ChatCompletionMessageParam`).
     *
     * `content` accepts text, null, or an array of content parts. Parts use the SDK's
     * `text`, `image_url` (with `detail`), `input_audio`, `file`, and `refusal` objects.
     */
    struct ChatCompletionMessageParam {
        std::string role;                                                       ///< `system`, `developer`, `user`, `assistant`, or `tool`.
        Json::Value content{};                                                  ///< String, content part array, or null.
        std::optional<std::string> name{};                                      ///< Participant name.
        std::optional<std::string> tool_call_id{};                              ///< Call answered by a `tool` message.
        std::optional<std::vector<ChatCompletionMessageToolCall>> tool_calls{}; ///< Assistant tool invocations.
        std::optional<std::string> refusal{};                                   ///< Assistant refusal.
        std::optional<Json::Value> audio{};                                     ///< Reference to previous audio, e.g. `{ "id": "..." }`.
        std::optional<std::string> reasoning_content{};                         ///< Vendor reasoning history.
        Json::Value extra_body{};                                               ///< Additional message fields, overriding the fields above.
    };

    /**
     * @brief Tool definition (`ChatCompletionToolUnionParam`).
     */
    struct ChatCompletionToolParam {
        std::string type{ "function" }; ///< `function` or `custom`.
        Json::Value function{};         ///< `name`, `description`, `parameters`, and optional `strict`.
        Json::Value custom{};           ///< `name`, `description`, and optional `format`.
    };

    /**
     * @brief Chat completion request; unset optional fields are omitted on the wire.
     *
     * JSON-valued fields retain SDK union shapes without restricting vendor extensions.
     */
    struct ChatCompletionCreateParams {
        std::vector<ChatCompletionMessageParam> messages;                                       ///< Conversation, oldest first.
        std::optional<std::string> model{};                                                     ///< Unset uses the configured model.
        std::optional<double> frequency_penalty{};                                              ///< Frequency penalty.
        std::optional<std::int64_t> max_tokens{};                                               ///< Deprecated token limit.
        std::optional<double> presence_penalty{};                                               ///< Presence penalty.
        std::optional<double> temperature{};                                                    ///< Sampling temperature.
        std::optional<double> top_p{};                                                          ///< Nucleus sampling probability.
        std::optional<std::vector<ChatCompletionToolParam>> tools{};                            ///< Function and custom tools.
        std::optional<Json::Value> tool_choice{};                                               ///< String choice, named tool, or `allowed_tools`.
        std::optional<bool> parallel_tool_calls{};                                              ///< Enable parallel tool calls.
        std::optional<Json::Value> response_format{};                                           ///< `text`, `json_object`, or `json_schema` object.
        std::optional<Json::Value> stop{};                                                      ///< A string or array of strings.
        std::optional<std::int64_t> max_completion_tokens{};                                    ///< Completion token limit, including reasoning.
        std::optional<std::int64_t> n{};                                                        ///< Candidate count.
        std::optional<std::int64_t> seed{};                                                     ///< Sampling seed.
        std::optional<bool> logprobs{};                                                         ///< Return token probabilities.
        std::optional<std::int64_t> top_logprobs{};                                             ///< Number of alternative token probabilities.
        std::optional<Json::Value> logit_bias{};                                                ///< Token IDs mapped to bias values.
        std::optional<std::string> reasoning_effort{};                                          ///< Model reasoning effort.
        std::optional<std::string> verbosity{};                                                 ///< Output verbosity.
        std::optional<std::string> safety_identifier{};                                         ///< End-user safety identifier.
        std::optional<std::string> prompt_cache_key{};                                          ///< Cache routing key.
        std::optional<std::string> user{};                                                      ///< Deprecated end-user identifier.
        std::optional<Json::Value> metadata{};                                                  ///< String metadata map.
        std::optional<bool> store{};                                                            ///< Store the completion for later management.
        std::optional<std::string> service_tier{};                                              ///< Requested service tier.
        std::optional<std::vector<std::string>> modalities{};                                   ///< Requested output modalities.
        std::optional<Json::Value> audio{};                                                     ///< Output audio `format` and `voice`.
        std::optional<Json::Value> prediction{};                                                ///< Predicted output content.
        std::optional<Json::Value> web_search_options{};                                        ///< Web search configuration.
        std::optional<std::string> prompt_cache_retention{};                                    ///< Cache retention policy.
        std::optional<Json::Value> prompt_cache_options{};                                      ///< Cache breakpoints.
        std::optional<Json::Value> moderation{};                                                ///< Input/output moderation settings.
        std::optional<Json::Value> stream_options{};                                            ///< `include_usage` and other stream options.
        Json::Value extra_body{};                                                               ///< Additional body members; overrides named fields.
        std::optional<Timeout> timeout{};                                                       ///< Override the client's timeout.
        std::optional<int> max_retries{};                                                       ///< Override the client's retry count.
        Headers extra_headers{};                                                                ///< Per-request headers.
        Json::Value extra_query{};                                                              ///< Per-request query parameters.
        std::function<Result<void>(Json::Value const&, Json::Value const&)> schema_validator{}; ///< Optional local validator receiving decoded content and the caller's JSON Schema; never serialized.
    };

    /**
     * @brief Audio generated with an assistant reply.
     */
    struct ChatCompletionAudio {
        std::string id;            ///< Reference ID for later conversation turns.
        std::int64_t expires_at{}; ///< Expiration timestamp.
        std::string data;          ///< Base64-encoded audio.
        std::string transcript;    ///< Audio transcript.
        Json::Value raw{};         ///< Complete audio object.
    };

    /**
     * @brief URL citation attached to an assistant reply.
     */
    struct ChatCompletionAnnotation {
        std::string type;           ///< Usually `url_citation`.
        Json::Value url_citation{}; ///< URL, title, and start/end character indexes.
        Json::Value raw{};          ///< Complete annotation.
    };

    /**
     * @brief An alternative token probability.
     */
    struct ChatCompletionTopLogprob {
        std::string token;                       ///< Token text.
        double logprob{};                        ///< Log probability.
        std::optional<std::vector<int>> bytes{}; ///< UTF-8 byte values; null when unavailable.
        Json::Value raw{};                       ///< Complete token record.
    };

    /**
     * @brief Token probability and its most likely alternatives.
     */
    struct ChatCompletionTokenLogprob {
        std::string token;                                  ///< Token text.
        double logprob{};                                   ///< Log probability.
        std::optional<std::vector<int>> bytes{};            ///< UTF-8 bytes.
        std::vector<ChatCompletionTopLogprob> top_logprobs; ///< Alternative tokens.
        Json::Value raw{};                                  ///< Complete token record.
    };

    /**
     * @brief Probabilities of content and refusal tokens.
     */
    struct ChatCompletionLogprobs {
        std::optional<std::vector<ChatCompletionTokenLogprob>> content{}; ///< Content probabilities.
        std::optional<std::vector<ChatCompletionTokenLogprob>> refusal{}; ///< Refusal probabilities.
        Json::Value raw{};                                                ///< Complete probability object.
    };

    /**
     * @brief Assistant response message.
     */
    struct ChatCompletionMessage {
        std::string role;                                                       ///< Normally `assistant`.
        std::optional<std::string> content{};                                   ///< Generated text.
        std::optional<std::string> reasoning_content{};                         ///< Vendor reasoning text.
        std::optional<std::vector<ChatCompletionMessageToolCall>> tool_calls{}; ///< Generated invocations.
        std::optional<std::string> refusal{};                                   ///< Refusal text.
        std::optional<std::vector<ChatCompletionAnnotation>> annotations{};     ///< Search citations.
        std::optional<ChatCompletionAudio> audio{};                             ///< Generated audio.
        std::optional<Json::Value> parsed{};                                    ///< Structured content decoded by `Parse`.
        Json::Value raw{};                                                      ///< Original message, including unknown fields.

        /**
         * @brief Preserve this reply as the next assistant request message.
         * @return Conversation message retaining tool calls and vendor fields.
         */
        [[nodiscard]] auto ToParam() const -> ChatCompletionMessageParam;
    };

    /**
     * @brief One generated alternative.
     */
    struct ChatCompletionChoice {
        std::string finish_reason;                        ///< `stop`, `length`, `tool_calls`, etc.
        std::int64_t index{};                             ///< Candidate index.
        ChatCompletionMessage message;                    ///< Generated reply.
        std::optional<ChatCompletionLogprobs> logprobs{}; ///< Token probabilities.
        Json::Value raw{};                                ///< Original choice.
    };

    /**
     * @brief Breakdown of generated tokens.
     */
    struct CompletionTokensDetails {
        std::optional<std::int64_t> reasoning_tokens{};           ///< Reasoning tokens.
        std::optional<std::int64_t> accepted_prediction_tokens{}; ///< Accepted predicted tokens.
        std::optional<std::int64_t> rejected_prediction_tokens{}; ///< Rejected predicted tokens.
        std::optional<std::int64_t> audio_tokens{};               ///< Generated audio tokens.
        std::optional<std::int64_t> text_tokens{};                ///< Generated text tokens.
        Json::Value raw{};                                        ///< Original breakdown.
    };

    /**
     * @brief Breakdown of prompt tokens.
     */
    struct PromptTokensDetails {
        std::optional<std::int64_t> cached_tokens{};      ///< Cache hits.
        std::optional<std::int64_t> cache_write_tokens{}; ///< Cache writes.
        std::optional<std::int64_t> audio_tokens{};       ///< Input audio tokens.
        std::optional<std::int64_t> image_tokens{};       ///< Input image tokens.
        std::optional<std::int64_t> text_tokens{};        ///< Input text tokens.
        Json::Value raw{};                                ///< Original breakdown.
    };

    /**
     * @brief Token usage for a completion.
     */
    struct CompletionUsage {
        std::int64_t completion_tokens{};                                   ///< Generated tokens.
        std::int64_t prompt_tokens{};                                       ///< Input tokens.
        std::int64_t total_tokens{};                                        ///< Total tokens.
        std::optional<CompletionTokensDetails> completion_tokens_details{}; ///< Generated token breakdown.
        std::optional<PromptTokensDetails> prompt_tokens_details{};         ///< Input token breakdown.
        Json::Value raw{};                                                  ///< All counters, including vendor cache fields.
    };

    /**
     * @brief A complete generated chat response.
     */
    struct ChatCompletion {
        std::string id;                                  ///< Completion ID.
        std::vector<ChatCompletionChoice> choices;       ///< Generated alternatives.
        std::int64_t created{};                          ///< Unix timestamp.
        std::string model;                               ///< Actual model.
        std::string object;                              ///< `chat.completion`.
        std::optional<CompletionUsage> usage{};          ///< Token usage.
        std::optional<std::string> system_fingerprint{}; ///< Backend fingerprint.
        std::optional<std::string> service_tier{};       ///< Actual service tier.
        std::optional<Json::Value> metadata{};           ///< Stored metadata.
        std::optional<Json::Value> moderation{};         ///< Moderation result.
        Json::Value raw{};                               ///< Complete original response (`to_dict`/`model_extra`).
        std::string _request_id;                         ///< Response `x-request-id`.
    };

    /**
     * @brief Partial tool invocation within a streaming delta.
     */
    struct ChatCompletionChunkToolCall {
        std::int64_t index{};                  ///< Index used to accumulate this call.
        std::optional<std::string> id{};       ///< Call ID, usually in its first delta.
        std::optional<std::string> type{};     ///< Tool type.
        std::optional<Json::Value> function{}; ///< Partial function name/arguments.
        std::optional<Json::Value> custom{};   ///< Partial custom name/input.
        Json::Value raw{};                     ///< Complete delta.
    };

    /**
     * @brief Incremental assistant message.
     */
    struct ChatCompletionChunkDelta {
        std::optional<std::string> role{};                                    ///< Message role.
        std::optional<std::string> content{};                                 ///< New text.
        std::optional<std::string> refusal{};                                 ///< New refusal text.
        std::optional<std::string> reasoning_content{};                       ///< New vendor reasoning text.
        std::optional<std::vector<ChatCompletionChunkToolCall>> tool_calls{}; ///< New tool fragments.
        Json::Value raw{};                                                    ///< Complete delta.
    };

    /**
     * @brief One candidate update in a chat stream.
     */
    struct ChatCompletionChunkChoice {
        std::int64_t index{};                             ///< Candidate index.
        ChatCompletionChunkDelta delta;                   ///< Incremental message.
        std::optional<std::string> finish_reason{};       ///< Set on a candidate's last update.
        std::optional<ChatCompletionLogprobs> logprobs{}; ///< New token probabilities.
        Json::Value raw{};                                ///< Complete choice update.
    };

    /**
     * @brief One server-sent chat completion chunk.
     */
    struct ChatCompletionChunk {
        std::string id;                                 ///< Completion ID.
        std::vector<ChatCompletionChunkChoice> choices; ///< Candidate updates; empty for usage-only chunks.
        std::int64_t created{};                         ///< Unix timestamp.
        std::string model;                              ///< Actual model.
        std::string object;                             ///< `chat.completion.chunk`.
        std::optional<CompletionUsage> usage{};         ///< Final usage when requested.
        Json::Value raw{};                              ///< Complete chunk.
        std::string _request_id;                        ///< Response `x-request-id`.
    };

    /**
     * @brief High-level stream event, named after the Python chat stream events.
     */
    struct ChatCompletionStreamEvent {
        std::string type;                         ///< `chunk`, `content.delta`, `content.done`, `refusal.*`, tool arguments, or logprobs.
        std::int64_t choice_index{};              ///< Candidate index.
        std::optional<std::int64_t> tool_index{}; ///< Tool index where relevant.
        std::string delta;                        ///< New text/arguments, or final text for a `done` event.
        Json::Value data{};                       ///< Event-specific details and token probabilities.
        ChatCompletion snapshot;                  ///< Accumulated completion at this event.
    };

} // namespace drogon_openai
